import * as React from "react";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";

/**
 * Cta — the UDS "[CTA]" screen-bottom action area.
 *
 * A bottom-anchored container that holds a page-level action (compose a
 * `ButtonGroup` as its children) and, by default, the OS bottom system UI
 * (iOS home indicator). It mirrors the Figma `[CTA]` set, whose only variant
 * axis is `onFrameHigh`:
 *   - `onFrameHigh` (false | true) → background matched to the underlying frame
 *     (`background/base/low` #fcfcfc vs `background/base/high` #f2f2f2).
 *   - `hasSystemUiBottom` (default true) → render the bottom system-UI safe area.
 *   - `systemUi` → replace the default home indicator with a custom node.
 *
 * Layout per Figma: the action wrapper pads `component/x/20` · `component/y/16`;
 * the action itself is whatever `ButtonGroup`/`Button`s you pass as `children`.
 * Colors/size of those buttons are owned by `Button`, not this container.
 *
 * Note: this is a *layout container*, not an interactive control — so it uses a
 * minimal `cva` for the background axis only (no focus ring / state overlay).
 */
const ctaVariants = cva("flex w-full flex-col items-stretch", {
  variants: {
    onFrameHigh: {
      false: "bg-background-base-low",
      true: "bg-background-base-high",
    },
  },
  defaultVariants: {
    onFrameHigh: false,
  },
});

export type CtaProps = React.HTMLAttributes<HTMLDivElement> & {
  /** Match the background to the underlying frame — `true` = base/high, `false` = base/low. Defaults to `false`. */
  onFrameHigh?: boolean;
  /** Render the bottom OS system-UI safe area (iOS home indicator). Defaults to `true`. */
  hasSystemUiBottom?: boolean;
  /** Replace the default home indicator with a custom system-UI node. */
  systemUi?: React.ReactNode;
};

const Cta = React.forwardRef<HTMLDivElement, CtaProps>(
  (
    { className, onFrameHigh = false, hasSystemUiBottom = true, systemUi, children, ...props },
    ref
  ) => (
    <div ref={ref} className={cn(ctaVariants({ onFrameHigh, className }))} {...props}>
      {/* Action wrapper — put a <ButtonGroup> here. */}
      <div className="flex w-full flex-col items-stretch px-component-x-20 py-component-y-16">
        {children}
      </div>
      {/* Bottom system UI (iOS home indicator) — overridable via `systemUi`. */}
      {hasSystemUiBottom &&
        (systemUi ?? (
          <div className="flex w-full items-center justify-center pb-2 pt-[21px]">
            <div className="h-[5px] w-[134px] rounded-full bg-container-base-black" />
          </div>
        ))}
    </div>
  )
);
Cta.displayName = "Cta";

export { Cta, ctaVariants };

import * as React from "react";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";

/**
 * ButtonGroup — the UDS button group, mirroring the Figma sets.
 *
 * Maps 1:1 to ALL FOUR Figma button-group sets — they share one layout
 * (gap/8, two buttons max) and differ only in which `Button` you compose,
 * which this layout-only wrapper delegates entirely:
 *   - `[Button Group] CTA`         → page `Button`s (55px)   · page-bottom CTA
 *   - `[Button Group] Bottom Sheet`→ page `Button`s (55px)   · inside a sheet
 *   - `[Button Group] Dialog`      → module `Button`s (44px) · confirm/cancel
 *   - `[Button Group] Card`        → module `Button`s (44px) · neutral card action
 *
 * A composition wrapper that arranges CTA `Button`s at the bottom of a screen,
 * a sheet, a dialog, or a card. It owns only *layout* (direction + gap + child
 * sizing); each button's size/color comes from the `Button` component, so every
 * Figma content pattern is expressed by the children you pass:
 *   - filled         → one filled `<Button>`                        · direction="row"
 *   - filled+filled  → two filled `<Button>`s, equal width          · direction="row"
 *   - filled+outline → an outline `<Button>` + a filled `<Button>`  · direction="row"
 *   - filled+ghost   → a filled `<Button>` + a ghost `<Button>`     · direction="column"
 *
 * Contexts differ only in the child `Button` props (all from `Button`, never
 * this wrapper):
 *   - CTA/Bottom Sheet (page): main = filled/primary (magenta); the paired
 *     secondary is a dark filled/secondary.
 *   - Dialog (module): main = filled/primary (magenta); paired secondary is a
 *     gray filled/tertiary (container/base/higher).
 *   - Card (module): main = neutral filled/secondary (dark); paired secondary
 *     is an outline/primary (filled+outline) or ghost/secondary.
 *
 * Layout per Figma (spacing/gap/8 between buttons):
 *   - row    → buttons share the width equally (flex-1)
 *   - column → buttons stack, each full width
 */
const buttonGroupVariants = cva("flex w-full gap-gap-8", {
  variants: {
    // The only Figma axis: how the buttons are laid out. Colors live on the
    // child `Button`s, not here.
    direction: {
      row: "flex-row items-stretch [&>*]:min-w-0 [&>*]:flex-1 [&>*]:basis-0",
      column: "flex-col items-stretch [&>*]:w-full",
    },
  },
  defaultVariants: {
    direction: "row",
  },
});

export type ButtonGroupProps = React.HTMLAttributes<HTMLDivElement> & {
  /**
   * Row = equal-width buttons side by side (filled · filled+filled);
   * column = full-width buttons stacked (filled+ghost). Defaults to `row`.
   */
  direction?: "row" | "column";
};

const ButtonGroup = React.forwardRef<HTMLDivElement, ButtonGroupProps>(
  ({ className, direction, children, ...props }, ref) => (
    <div
      ref={ref}
      role="group"
      className={cn(buttonGroupVariants({ direction, className }))}
      {...props}
    >
      {children}
    </div>
  )
);
ButtonGroup.displayName = "ButtonGroup";

export { ButtonGroup, buttonGroupVariants };

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";

/**
 * Button — the unified UDS button, mirroring the Figma "[Button]" component sets.
 *
 * A single component with a `category` axis that maps 1:1 to Figma:
 *   - `page`   → "[Button] Page"   · 55px · page-level CTA        (filled·ghost)
 *   - `module` → "[Button] Module" · 44px · module/content action (filled·outline·ghost, +tertiary on filled)
 *   - `inline` → "[Button] Inline" · 33px · inline/text action    (filled·outline·ghost)
 *
 * Only the `category × variant × hierarchy` combinations that Figma actually
 * defines are valid — the `ButtonProps` union makes every other combination a
 * compile error (e.g. an outline `page` button, or a `tertiary` outline).
 *
 * Interaction states are CSS, not props (Figma exposes a `state` variant for
 * design only; in code hover/pressed/focus are browser-driven and `disabled`
 * is the native attribute):
 *   - hover / pressed → state-layer overlay (::before)
 *   - focused         → 1px ring, status/border/selected, 4px offset
 *   - disabled        → status/container|border|text/disabled
 *
 * Every value is bound to a Figma design token (no raw Tailwind scale).
 */
const buttonVariants = cva(
  [
    "relative isolate inline-flex select-none items-center justify-center",
    "gap-gap-4 rounded-small font-sans font-base leading-none transition-colors",
    "focus-visible:outline-none focus-visible:ring-[1px] focus-visible:ring-status-border-selected focus-visible:ring-offset-[4px] focus-visible:ring-offset-frame-base-low",
    "disabled:pointer-events-none [&_svg]:shrink-0",
    // state-layer overlay for hover & pressed (color set per compound variant below)
    "before:pointer-events-none before:absolute before:inset-0 before:rounded-[inherit] before:opacity-0 before:transition-opacity hover:before:opacity-100 active:before:opacity-100",
  ],
  {
    variants: {
      // Geometry + typography per category. Colors live in compoundVariants.
      category: {
        page: "px-component-x-20 py-component-y-14 text-label-large [&_svg]:size-6",
        module: "px-component-x-20 py-component-y-10 text-label-large [&_svg]:size-6",
        inline: "min-h-[33px] px-component-x-12 py-component-y-8 text-label-medium [&_svg]:size-4",
      },
      variant: { filled: "", outline: "border", ghost: "" },
      hierarchy: { primary: "", secondary: "", tertiary: "" },
    },
    compoundVariants: [
      // ── page ("[Button] Page", 55px) ──────────────────────────────────
      {
        category: "page",
        variant: "filled",
        hierarchy: "primary",
        className:
          "bg-container-brand-primary-high text-text-base-white before:bg-state-state-layer-pressed-inverse-black disabled:bg-status-container-disabled disabled:text-status-text-disabled",
      },
      {
        category: "page",
        variant: "filled",
        hierarchy: "secondary",
        className:
          "bg-container-brand-secondary text-text-base-white before:bg-state-state-layer-pressed-white disabled:bg-status-container-disabled disabled:text-status-text-disabled",
      },
      {
        // page ghost has a single (secondary) style in Figma — hierarchy-agnostic.
        category: "page",
        variant: "ghost",
        className:
          "bg-transparent text-text-base-primary before:bg-state-state-layer-pressed-inverse-black disabled:bg-transparent disabled:text-status-text-disabled",
      },

      // ── module ("[Button] Module", 44px) ──────────────────────────────
      {
        category: "module",
        variant: "filled",
        hierarchy: "primary",
        className:
          "bg-container-brand-primary-high text-text-base-white before:bg-state-state-layer-pressed-inverse-black disabled:bg-status-container-disabled disabled:text-status-text-disabled",
      },
      {
        category: "module",
        variant: "filled",
        hierarchy: "secondary",
        className:
          "bg-container-brand-secondary text-text-base-white before:bg-state-state-layer-pressed-white disabled:bg-status-container-disabled disabled:text-status-text-disabled",
      },
      {
        category: "module",
        variant: "filled",
        hierarchy: "tertiary",
        className:
          "bg-container-base-higher-level1 text-text-base-primary before:bg-state-state-layer-pressed-inverse-black disabled:bg-status-container-disabled disabled:text-status-text-disabled",
      },
      {
        category: "module",
        variant: "outline",
        hierarchy: "primary",
        className:
          "border-border-brand-secondary bg-container-base-low text-text-base-primary before:bg-state-state-layer-pressed-inverse-black disabled:border-status-border-disabled disabled:text-status-text-disabled",
      },
      {
        category: "module",
        variant: "outline",
        hierarchy: "secondary",
        className:
          "border-border-base-higher bg-container-base-low text-text-base-primary before:bg-state-state-layer-pressed-inverse-black disabled:border-status-border-disabled disabled:text-status-text-disabled",
      },
      {
        category: "module",
        variant: "ghost",
        hierarchy: "primary",
        className:
          "bg-transparent text-text-brand-primary-high before:bg-state-state-layer-pressed-inverse-black disabled:text-status-text-disabled",
      },
      {
        category: "module",
        variant: "ghost",
        hierarchy: "secondary",
        className:
          "bg-transparent text-text-base-primary before:bg-state-state-layer-pressed-inverse-black disabled:text-status-text-disabled",
      },

      // ── inline ("[Button] Inline", 33px) ──────────────────────────────
      {
        category: "inline",
        variant: "filled",
        hierarchy: "primary",
        className:
          "bg-container-brand-secondary text-text-base-white before:bg-state-state-layer-pressed-white disabled:bg-status-container-disabled disabled:text-status-text-disabled",
      },
      {
        category: "inline",
        variant: "filled",
        hierarchy: "secondary",
        className:
          "bg-container-base-higher-level1 text-text-base-primary before:bg-state-state-layer-pressed-inverse-black disabled:bg-status-container-disabled disabled:text-status-text-disabled",
      },
      {
        category: "inline",
        variant: "outline",
        hierarchy: "primary",
        className:
          "border-border-brand-secondary bg-container-base-low text-text-base-primary before:bg-state-state-layer-pressed-inverse-black disabled:bg-status-container-disabled disabled:border-status-border-disabled disabled:text-status-text-disabled",
      },
      {
        category: "inline",
        variant: "outline",
        hierarchy: "secondary",
        className:
          "border-border-base-higher bg-container-base-low text-text-base-primary before:bg-state-state-layer-pressed-inverse-black disabled:bg-status-container-disabled disabled:border-status-border-disabled disabled:text-status-text-disabled",
      },
      {
        category: "inline",
        variant: "ghost",
        hierarchy: "primary",
        className:
          "bg-transparent text-text-brand-primary-high before:bg-state-state-layer-pressed-inverse-black disabled:text-status-text-disabled",
      },
      {
        category: "inline",
        variant: "ghost",
        hierarchy: "secondary",
        className:
          "bg-transparent text-text-base-primary before:bg-state-state-layer-pressed-inverse-black disabled:text-status-text-disabled",
      },
    ],
    defaultVariants: {
      category: "page",
      variant: "filled",
      hierarchy: "primary",
    },
  }
);

/**
 * Figma-defined `category × variant × hierarchy` combinations — and only those.
 * `category` is optional and defaults to `page`, so `<Button>` alone is a
 * page/filled/primary button.
 */
type ButtonVariantProps =
  // page — "[Button] Page": filled(primary·secondary), ghost(secondary)
  | { category?: "page"; variant?: "filled"; hierarchy?: "primary" | "secondary" }
  | { category?: "page"; variant: "ghost"; hierarchy?: "secondary" }
  // module — "[Button] Module": filled(primary·secondary·tertiary), outline·ghost(primary·secondary)
  | { category: "module"; variant?: "filled"; hierarchy?: "primary" | "secondary" | "tertiary" }
  | { category: "module"; variant: "outline" | "ghost"; hierarchy?: "primary" | "secondary" }
  // inline — "[Button] Inline": filled·outline·ghost(primary·secondary)
  | { category: "inline"; variant?: "filled" | "outline" | "ghost"; hierarchy?: "primary" | "secondary" };

type ButtonOwnProps = {
  /** Render as the child element (e.g. an `<a>`) instead of a `<button>`. Icons are ignored in this mode. */
  asChild?: boolean;
  /** Leading icon (24px for page/module, 16px for inline). */
  iconStart?: React.ReactNode;
  /** Trailing icon (24px for page/module, 16px for inline). */
  iconEnd?: React.ReactNode;
};

export type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement> &
  ButtonOwnProps &
  ButtonVariantProps;

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, category, variant, hierarchy, asChild = false, iconStart, iconEnd, children, ...props }, ref) => {
    const Comp = asChild ? Slot : "button";
    return (
      <Comp
        ref={ref}
        className={cn(buttonVariants({ category, variant, hierarchy, className }))}
        {...props}
      >
        {asChild ? (
          children
        ) : (
          <>
            {iconStart}
            {children}
            {iconEnd}
          </>
        )}
      </Comp>
    );
  }
);
Button.displayName = "Button";

export { Button, buttonVariants };

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/** Merge conditional class names and de-conflict Tailwind utilities. */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
